/bin/bash -c "PYTHONPATH=/opt/galaxy_agent python - <<'PY'
import galaxy_execute_mcp_core as c
import json
queries=['Ensembl REST','REST API','ensembl_rest','ID mapping','gene annotation','Genomic Region','UCSC Table','liftOver','NCBI Datasets Gene','UniProt REST','MyGene.info','biomart','gene symbol to Ensembl','RefSeq to Ensembl']
for q in queries:
    try:
        r=c.search_galaxy_tools(q)
        print('\\n###',q,'status',r.get('status'),'matching',r.get('matching_tool_count'))
        for x in r.get('results',[]):
            print(x.get('name'),'|',x.get('tool_id'),'|',x.get('panel_section'))
    except Exception as e:
        print('ERR',q,e)
PY"

