/bin/bash -c "PYTHONPATH=/opt/galaxy_agent python - <<'PY'
import requests, os, json
url=os.environ.get('GALAXY_URL','https://usegalaxy.org').rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
for q in ['ucsc','table browser','ensembl','biomart','region','gene','ncbi']:
    r=requests.get(url+'/api/tools', params={'q':q}, headers={'x-api-key':key}, timeout=60)
    print('\\nQUERY',q,'status',r.status_code)
    try:
      data=r.json()
      print('type',type(data),'len',len(data) if hasattr(data,'__len__') else '')
      if isinstance(data,list):
       for x in data[:100]: print(x)
      else: print(str(data)[:2000])
    except Exception as e: print('json err',e, r.text[:1000])
PY"

